function formatarNome(nome) {
  return nome
    .trim()
    .split(/\s+/)
    .map((palavra) => palavra.at(0).toUpperCase() + palavra.slice(1).toLowerCase())
    .join(" ");
}

console.log(formatarNome("  ana PAULA   silva ")); // "Ana Paula Silva"

function criarLinhaFatura(produto, preco) {
  const nomeAlinhado = produto.padEnd(20);
  const precoAlinhado = `${preco}`.padStart(10);
  return `${nomeAlinhado}${precoAlinhado} €`;
}

console.log(criarLinhaFatura("Teclado", 49));
console.log(criarLinhaFatura("Teclado", 49).length); // 32

function mascararEmail(email) {
  const [utilizador, dominio] = email.split("@");
  const visivel = utilizador.slice(0, 2);
  const oculto = visivel.padEnd(utilizador.length, "*");
  return `${oculto}@${dominio}`;
}

console.log(mascararEmail("adriano.toledo@casais.pt")); // "ad************@casais.pt"

function ehPalindromo(texto) {
  const normalizado = texto.toLowerCase().replaceAll(/[^a-zà-ú]/g, "");
  const invertido = normalizado.split("").reverse().join("");
  return normalizado === invertido;
}

console.log(ehPalindromo("A sacada da casa")); // true
console.log(ehPalindromo("Isto não é um palíndromo")); // false
